import {mountInteraction} from './reference.js';
import {typeStream,demoStream,httpStream,escapeHTML as safe,markdown} from './stream.js';
const pages=await fetch('/assets/interaction-pages.json').then(r=>r.json());
const aiConfiguration=await fetch('/api/config').then(r=>r.ok?r.json():null).catch(()=>null);
for(const href of ['/assets/chat-source.css','/assets/interaction.css']){const link=document.createElement('link');link.rel='stylesheet';link.href=href;await new Promise((resolve,reject)=>{link.onload=resolve;link.onerror=reject;document.head.append(link);});}
let cleanup=()=>{};
const genres=['Romance','Fantasy','Sci-Fi','Boys Love','Girls Love','History','Horror','Slice of Life','Oriental Fantasy','Fan Fiction','Utility','Others'];
const triangle='<svg viewBox="0 0 24 24"><path d="m7 4 13 8-13 8z" fill="currentColor"/></svg>';
const arrow='<svg viewBox="0 0 24 24"><path d="M18.379 12.876H3v-1.6h15.379L13.684 6.58l1.132-1.131 6.625 6.626-6.625 6.625-1.132-1.131z" fill="currentColor"/></svg>';
function modal(title,content,onSave){const d=document.createElement('dialog');d.className='interaction-modal';d.innerHTML=`<button class="modal-close" aria-label="Close">×</button><h2>${safe(title)}</h2>${content}`;document.body.append(d);d.querySelector('.modal-close').onclick=()=>d.close();d.addEventListener('close',()=>d.remove());d.addEventListener('click',e=>{if(e.target===d)d.close();});if(onSave)d.querySelector('.save').onclick=()=>{onSave(d);d.close();};d.showModal();return d;}
function onboard(path,h){const step=Math.min(4,Math.max(1,Number(path.split('/')[2])||1));const profile=h.read('ooc-profile',{name:'nezuko',audience:'Male',genres:[...genres]});const root=mountInteraction(pages[step===1||step===2?'name':step===3?'preferences':'complete'],h);const buttons=()=>[...root.querySelectorAll('button')];const button=t=>buttons().find(b=>b.textContent.trim()===t);const progress=root.querySelector('[role=progressbar]');progress.setAttribute('aria-valuenow',String(step*25));progress.setAttribute('aria-valuetext',step*25+'%');progress.firstElementChild.style.transform=`translateX(-${100-step*25}%)`;
 root.insertAdjacentHTML('beforeend','<small class="onboarding-demo">Independent demo · preferences saved on this device</small>');
 const close=buttons().find(b=>!b.textContent.trim());if(close&&step<4){close.setAttribute('aria-label','Close onboarding');close.onclick=()=>h.navigate('/');}
 const persist=()=>h.save('ooc-profile',profile);const policy=root.querySelector('a[href*="/policy/service"]')?.parentElement;if(policy)policy.innerHTML='Demo preferences stay on this device. <a href="https://ooc.ai/policy/service/us/10142026" target="_blank" rel="noopener noreferrer">Original Terms</a> and <a href="https://ooc.ai/policy/privacy/us/09092026" target="_blank" rel="noopener noreferrer">Privacy Policy</a>.';
 if(step<=2){const input=root.querySelector('input'),heading=root.querySelector('h2'),caption=heading.nextElementSibling,next=button('Next');
  if(step===1){heading.textContent='Enter your birthdate';caption.textContent='Select your date of birth.';input.type='date';input.classList.add('date-picker');input.setAttribute('aria-label','Birthdate');input.removeAttribute('placeholder');input.value='';input.max=new Date().toISOString().slice(0,10);input.closest('.relative')?.querySelector('button')?.remove();const counter=[...root.querySelectorAll('span,div')].find(e=>/^6\/24$/.test(e.textContent.trim())&&e.children.length===0);if(counter)counter.textContent='';next.disabled=true;input.oninput=()=>next.disabled=!input.value||!input.checkValidity();next.onclick=()=>{if(input.value&&input.checkValidity())h.navigate('/onboarding/2');};}
  else{input.value=profile.name;input.maxLength=24;input.setAttribute('aria-label','Your name');const counter=[...root.querySelectorAll('*')].find(e=>e.children.length===0&&/^6\/24$/.test(e.textContent.trim()));const update=()=>{if(counter)counter.textContent=input.value.length+'/24';next.disabled=!input.value.trim();};input.oninput=update;update();buttons().filter(b=>!b.textContent.trim()&&b!==close).forEach(b=>b.onclick=()=>{input.value='';update();input.focus();});next.onclick=()=>{profile.name=input.value.trim();persist();h.navigate('/onboarding/3');};}
 }
 if(step===3){for(const b of buttons()){const label=b.textContent.trim();if(genres.includes(label)){const paint=()=>{const selected=profile.genres.includes(label);b.classList.toggle('border-brand',selected);b.classList.toggle('text-brand',selected);b.classList.toggle('border-border',!selected);b.classList.toggle('text-gray-1',!selected);b.setAttribute('aria-pressed',String(selected));};paint();b.onclick=()=>{profile.genres=profile.genres.includes(label)?profile.genres.filter(g=>g!==label):[...profile.genres,label];paint();persist();};}}
  root.querySelectorAll('[role=radio]').forEach((b,i)=>{const value=['Male','Female','Neutral'][i];b.setAttribute('aria-label',value);b.onclick=()=>{profile.audience=value;root.querySelectorAll('[role=radio]').forEach((r,j)=>{const checked=j===i;r.setAttribute('aria-checked',String(checked));r.dataset.state=checked?'checked':'unchecked';r.innerHTML=checked?'<span class="flex items-center justify-center"><svg viewBox="0 0 24 24" class="size-2.5 fill-primary"><circle cx="12" cy="12" r="12"/></svg></span>':'';});persist();};if(value===profile.audience)b.onclick();});button('Previous').onclick=()=>h.navigate('/onboarding/2');button('Next').onclick=()=>{persist();h.navigate('/onboarding/4');};
 }
 if(step===4){root.querySelectorAll('a[href^="/story/"]').forEach(a=>{a.href='/play/'+a.getAttribute('href').split('/')[2];});button("I'll give up the free tutorial").onclick=()=>h.navigate('/');const track=root.querySelector('[aria-roledescription=carousel]')||root.querySelector('[role=region]');if(track){const slides=track.querySelector('[style*="translate"]')||track.querySelector('.flex');let index=0;for(const [label,direction]of [['Next slide',1],['Previous slide',-1]]){const b=button(label);if(b){b.disabled=false;b.onclick=()=>{index=Math.max(0,Math.min(4,index+direction));if(slides)slides.style.transform=`translateX(-${index*50}%)`;};}}}}
 document.title='Set up your profile · OOC replica';return true;
}
function session(id,h){const title=h.data.find(d=>d.id===id)||h.data[0];const isCharacter=title.type==='character'||id==='6a808dbe8cc39ab3d8abaf5e';const root=mountInteraction(pages[isCharacter?'character':'story'],h);const q=s=>root.querySelector(s);const body=q('#session-messages'),scroll=q('#session-scroll'),input=q('#session-input'),send=q('[data-control=send]'),settings=q('#session-settings');body.classList.toggle('character',isCharacter);const profile=h.read('ooc-profile',{name:'nezuko'});const name=profile.name||'nezuko';const key='ooc-session-v2-'+id;let messages=h.read(key,[]),controller,state='ready',follow=true,disposed=false;let transport=h.read('ooc-response-mode',aiConfiguration?.configured?'ai':'demo');
 const titleLink=root.querySelector(`a[href="/${isCharacter?'character':'story'}/${isCharacter?'6a808dbe8cc39ab3d8abaf5e':'69f414d90abbab6f6a2c8131'}"]`);if(titleLink){titleLink.href=`/${isCharacter?'character':'story'}/${id}`;const label=[...titleLink.querySelectorAll('*')].find(e=>e.children.length===0&&e.textContent.trim()===(isCharacter?'Your New beautiful neighbour':'Lumencia Academy'));if(label)label.textContent=title.title;}
 const settingsTitle=settings.querySelector('p');if(settingsTitle)settingsTitle.textContent=title.title;
 const save=()=>h.save(key,messages);const value=()=>input.tagName==='TEXTAREA'?input.value:input.innerText;const setValue=v=>{if(input.tagName==='TEXTAREA')input.value=v;else input.textContent=v;updateSend();};
 const updateSend=()=>{send.setAttribute('aria-label',state==='streaming'?'Stop generating':state==='submitted'?'Waiting for response':value().trim()?'Send message':'Continue story');send.disabled=state==='submitted';send.innerHTML=state==='submitted'?'<span class="session-spinner"></span>':state==='streaming'?'<svg viewBox="0 0 24 24"><rect x="6" y="6" width="12" height="12" rx="2" fill="currentColor"/></svg>':value().trim()?arrow:triangle;};
 const intro=isCharacter?`*A new neighbour knocks at your door.*\n\n*Ashley smiles.* “Hi, you must be ${name}. I just moved in next door. It's nice to meet you!”`:`> Character Preview\n\n*The academy gates open. A new adventure awaits ${name}.*`;
 const suggestions=isCharacter?['Welcome! Is there a café nearby?','Tell me about yourself.','Would you like to explore the neighbourhood?']:['Where can I find the library?','I head toward the courtyard.','Tell me about the academy.'];
 const renderMessages=()=>{const atBottom=follow;body.innerHTML=`<div class="session-demo">${transport==='demo'?'Demo · simulated responses':'AI · live streaming · '+safe(aiConfiguration?.model||'configured model')}<button data-mode>Change mode</button><button data-onboard>Profile</button></div><div class="session-message">${(id==='69f414d90abbab6f6a2c8131'||id==='6a808dbe8cc39ab3d8abaf5e')?pages[isCharacter?'characterIntro':'storyIntro'].replaceAll('nezuko',safe(name)):markdown(intro)}${isCharacter&&id!=='6a808dbe8cc39ab3d8abaf5e'?`<img class="session-empty-preview" style="width:320px" src="${safe(title.image)}" alt="${safe(title.title)}">`:''}</div>`+messages.map((m,i)=>`<article class="session-message ${m.role==='user'?'user':''} ${m.streaming?'streaming':''}" data-index="${i}"><div class="message-content">${markdown(m.text)}</div>${m.role==='assistant'&&!m.streaming?`<div class="message-tools"><button aria-label="Regenerate response" data-regenerate="${i}">↻</button><button aria-label="Message options" data-options="${i}">⋮</button></div>`:''}${m.stopped?'<small class="session-demo">Stopped</small>':''}</article>`).join('');if(state==='ready')body.insertAdjacentHTML('beforeend',`<div class="session-suggestions">${suggestions.map((s,i)=>`<div class="suggestion"><button aria-label="Edit suggested response" data-edit="${i}">✎</button><p>${safe(s)}</p><button aria-label="Send suggested response" data-suggest="${i}">➜</button></div>`).join('')}</div>`);if(atBottom)scroll.scrollTop=scroll.scrollHeight;};
 async function generate(text,{regenerate=false}={}){if(state!=='ready'||disposed)return;if(!regenerate)messages.push({role:'user',text});const answer={role:'assistant',text:'',streaming:true};messages.push(answer);controller=new AbortController();state='submitted';follow=true;setValue('');renderMessages();updateSend();const reply=isCharacter?`*Ashley turns back with a warm smile.*\n\n“There's a lovely café just around the corner. The coffee is good, and it's quiet enough to read. I can show you the way, ${name}.”\n\n*She gestures toward the tree-lined street, waiting for your reply.*`:`> D0 | Wednesday | 10:00 | Lumencia Academy - Grand Hall\n\n*Sunlight spills across the marble floor. A student carrying a stack of books pauses beside ${name}.*\n\n💬 Sia | “The library is past the fountain, then the first door on your left. Are you here to study, or would you like a tour?”\n\n*The courtyard bell rings as students pass through the archway.*\n\n\`\`\`info\nTier: Beginner | Affiliation: Lumencia Academy\nStatus: Normal 🟢\nInventory: Academy guide\nRelationships: Sia [Friendly]\n\`\`\``;
  try{const source=transport==='demo'?demoStream(reply,controller.signal):httpStream(messages.filter(m=>m!==answer).map(m=>({role:m.role,content:m.text})),controller.signal,{titleId:id,profile:{name,audience:profile.audience},userNote:h.read('ooc-User Note-'+id,''),memory:h.read('ooc-Memories-'+id,''),outputLength:h.read('ooc-output-length','standard')});await typeStream(source,{signal:controller.signal,onText:t=>{if(disposed)return;answer.text=t;const el=body.querySelector(`[data-index="${messages.length-1}"] .message-content`);if(el)el.innerHTML=markdown(t);if(follow)scroll.scrollTop=scroll.scrollHeight;},onState:s=>{if(disposed)return;state=s;updateSend();},step:matchMedia('(prefers-reduced-motion: reduce)').matches?24:3});answer.stopped=controller.signal.aborted;}catch(e){if(!disposed){answer.text=answer.text||'Unable to generate a response.';modal('Response unavailable',`<p>${safe(e.message)}</p><p>Demo mode works without an AI key.</p>`);}}finally{answer.streaming=false;save();if(!disposed){state='ready';renderMessages();updateSend();}}}
 if(transport==='ai'&&aiConfiguration?.configured){const model=q('[data-control=model]');model.querySelector('span').textContent=aiConfiguration.model;model.title='Model comes from the server configuration';}const sidebar=root.querySelector('[data-shrink]');sidebar.insertAdjacentHTML('beforeend',`<button class="session-profile" data-onboard><span>${safe(name.slice(0,1).toUpperCase())}</span>${safe(name)}</button>`);const toggleSidebar=()=>{const small=sidebar.dataset.shrink!=='true';sidebar.dataset.shrink=String(small);sidebar.nextElementSibling.style.marginLeft=matchMedia('(min-width:1024px)').matches?(small?'48px':'256px'):'';};if(sidebar)sidebar.querySelector('button').onclick=toggleSidebar;const showSettings=()=>settings.classList.toggle('session-open');const stop=()=>controller?.abort();send.onclick=()=>state==='streaming'?stop():generate(value().trim()||'Continue the scene.');input.oninput=()=>{if(input.tagName==='TEXTAREA'){input.style.height='45px';input.style.height=Math.min(171,input.scrollHeight)+'px';}updateSend();};input.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();if(state==='ready')send.click();}if(e.key==='Escape')input.blur();};scroll.onscroll=()=>{follow=scroll.scrollHeight-scroll.clientHeight-scroll.scrollTop<80;const jump=q('[data-control=bottom]');if(jump)jump.style.opacity=follow?'0':'1';};
 const showNote=label=>{const noteKey='ooc-'+label+'-'+id;modal(label,`<textarea aria-label="${safe(label)}" rows="8" maxlength="4000">${safe(h.read(noteKey,''))}</textarea><p class="session-demo">Saved locally in this demo.</p><button class="save">Save</button>`,d=>h.save(noteKey,d.querySelector('textarea').value));};
 const shortcuts=()=>modal('Keyboard shortcuts','<div class="shortcut-grid">'+[['Panels',[['Toggle Side Navigation','Ctrl+Shift+S'],['Toggle Session Settings','Ctrl+0'],['Toggle User Notes','Ctrl+I'],['Toggle Memories','Ctrl+Shift+U']]],['Input Field',[['Focus Input Field','↵'],['Unfocus Input Field','Esc']]],['Autosuggestion',[['Show Autosuggestion','Ctrl+/'],['Select Suggested Response','Ctrl+1~3']]],['Play Actions',[['Start New Session','Ctrl+Alt+N'],['Add Situation','Ctrl+Shift+E'],['Regenerate','Ctrl+Alt+R']]]].map(([group,rows])=>`<section><b>${group}</b>${rows.map(([a,b])=>`<div class="shortcut-row"><span>${a}</span><kbd>${b}</kbd></div>`).join('')}</section>`).join('')+'</div>');
 root.onclick=e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.control==='settings')showSettings();if(d.control==='bottom'){follow=true;scroll.scrollTop=scroll.scrollHeight;}if(d.control==='situation')modal('Add Situation','<textarea aria-label="Situation" rows="4" placeholder="Describe the situation"></textarea><button class="save">Add</button>',dialog=>{const t=dialog.querySelector('textarea').value.trim();if(t)generate(t);});if(d.control==='slash'){const pop=document.createElement('div');pop.className='session-popover';pop.innerHTML=['/continue','/situation','/regenerate'].map(t=>`<button>${t}</button>`).join('');root.append(pop);pop.onclick=event=>{const cmd=event.target.textContent;if(cmd==='/regenerate')regenerate();else if(cmd==='/continue')generate('Continue the scene.');else setValue('*Describe the situation*');pop.remove();};}if(d.control==='suggest'){follow=true;scroll.scrollTop=scroll.scrollHeight;}if(d.control==='model'&&transport==='ai'){modal('AI model',`<p>${safe(aiConfiguration?.model||'Not configured')}</p><p>The same role and style prompts apply when the server model changes.</p>`);return;}if(d.control==='model'){const pop=document.createElement('div');pop.className='session-popover';pop.innerHTML=[['Max','Uncompromising realism'],['Superb','Best quality, most immersive'],['Skillful','Vivid and descriptive narratives'],['Extensive','Strong details and long narratives'],['Basic','Light and cheap']].map(([a,c])=>`<button data-tier="${a}"><span>${a}<small>${c}</small></span><small>Demo</small></button>`).join('');root.append(pop);pop.onclick=event=>{const tier=event.target.closest('[data-tier]');if(tier){b.querySelector('span').textContent=tier.dataset.tier;h.save('ooc-model-tier',tier.dataset.tier);pop.remove();}};}
  if(d.edit!==undefined){setValue(suggestions[Number(d.edit)]);input.focus();}if(d.suggest!==undefined)generate(suggestions[Number(d.suggest)]);if(d.regenerate!==undefined)regenerate(Number(d.regenerate));if(d.options!==undefined){const i=Number(d.options);modal('Message options',`<textarea aria-label="Edit message" rows="7">${safe(messages[i].text)}</textarea><button class="save">Save</button>`,dialog=>{messages[i].text=dialog.querySelector('textarea').value;save();renderMessages();});}
  if('onboard'in d)h.navigate('/onboarding/2');if('mode'in d)modal('Response mode',`<select aria-label="Response mode"><option value="demo" ${transport==='demo'?'selected':''}>Demo (simulated streaming)</option><option value="ai" ${transport==='ai'?'selected':''} ${aiConfiguration?.configured?'':'disabled'}>AI ${aiConfiguration?.configured?'(live streaming)':'(not configured)'}</option></select><button class="save">Save</button>`,dialog=>{transport=dialog.querySelector('select').value;h.save('ooc-response-mode',transport);h.navigate('/play/'+id);});
  if(b.getAttribute('aria-haspopup')==='menu'&&!b.dataset.options)modal('Message options','<p>The initial scene is read-only in this demo.</p>');const label=b.textContent.trim();if(label==='User Note'||label==='Memories')showNote(label);if(label==='Keyboard Shortcuts')shortcuts();if(label==='Output Length')modal(label,'<select aria-label="Output length"><option>Standard</option><option>Short</option><option>Long</option></select><button class="save">Save</button>',dialog=>h.save('ooc-output-length',dialog.querySelector('select').value));if(label==='Avatars')modal('Avatars',`<input aria-label="Avatar name" maxlength="24" value="${safe(name)}"><button class="save">Save</button>`,dialog=>{h.save('ooc-profile',{...profile,name:dialog.querySelector('input').value.trim()||'nezuko'});});if(label==='Play Guide')modal('Play Guide','<p>Write a message, or describe an action with *asterisks*. Enter sends your message; Shift+Enter adds a line. Use the square button to stop a reply.</p><p class="session-demo">Demo responses are simulated.</p>');if(label.includes('Image Gallery'))modal('Image Gallery',`<img style="max-height:65vh;max-width:100%;margin:auto" src="${safe(title.image)}" alt="${safe(title.title)}">`);
 };
 function regenerate(index=messages.length-1){if(state!=='ready')return;const user=messages.slice(0,index).findLast(m=>m.role==='user');if(!user)return;messages=messages.slice(0,index);generate(user.text,{regenerate:true});}
 root.querySelectorAll('[data-control]').forEach(b=>{if(!b.getAttribute('aria-label'))b.setAttribute('aria-label',({settings:'Session settings',model:'Response model',situation:'Add situation',slash:'Slash commands',suggest:'Suggested responses'})[b.dataset.control]||b.dataset.control);});settings.querySelectorAll('[role=switch]').forEach(b=>b.onclick=()=>{const checked=b.getAttribute('aria-checked')!=='true';b.setAttribute('aria-checked',String(checked));b.dataset.state=checked?'checked':'unchecked';b.firstElementChild.dataset.state=b.dataset.state;});
 const keydown=e=>{if(document.querySelector('.interaction-modal[open]'))return;if(e.ctrlKey&&e.shiftKey&&e.key.toLowerCase()==='s'){e.preventDefault();toggleSidebar();}if(e.ctrlKey&&e.key==='0'){e.preventDefault();showSettings();}if(e.ctrlKey&&e.key.toLowerCase()==='i'){e.preventDefault();showNote('User Note');}if(e.ctrlKey&&e.shiftKey&&e.key.toLowerCase()==='u'){e.preventDefault();showNote('Memories');}if(e.ctrlKey&&e.shiftKey&&e.code==='Slash'){e.preventDefault();shortcuts();}if(e.ctrlKey&&e.altKey&&e.key.toLowerCase()==='r'){e.preventDefault();regenerate();}if(e.ctrlKey&&['1','2','3'].includes(e.key)){e.preventDefault();generate(suggestions[Number(e.key)-1]);}};document.addEventListener('keydown',keydown);cleanup=()=>{disposed=true;stop();document.removeEventListener('keydown',keydown);document.querySelectorAll('.interaction-modal').forEach(d=>d.remove());};
 root.querySelectorAll('a[href="/profile"]').forEach(a=>a.remove());renderMessages();updateSend();document.title=title.title+' · OOC replica';return true;
}
export function show(path,helpers){cleanup();cleanup=()=>{};if(path.startsWith('/onboarding'))return onboard(path,helpers);if(path.startsWith('/play/'))return session(path.split('/')[2],helpers);return false;}
